/**
 * The assistant's skills pack (spec goal 12): four short rule files the chat always reads and MCP
 * exposes as resources. The .md files under `skills/` are the source; they ship as string
 * constants (`skills-text.ts`, generated by `pnpm gen:skills`) because tsc does not copy .md files
 * into dist. The copy skill gets the app's live lint lists appended, so the words the model is told
 * to avoid are exactly the words `lintCopy` rejects.
 */
import { AI_TELLS, BANNED_WORDS } from '../text/lint.js';
import { SKILL_FILES } from './skills-text.js';

export type Skill = { name: string; title: string; text: string };

const ORDER = ['cinematic', 'continuity', 'copy', 'hooks'] as const;

/** The exact lists `server/src/text/lint.ts` enforces (never a copy that can drift). */
export function lintListText(): string {
  return [
    '## Exact lint list (the app rejects these in narration, titles and captions)',
    `- Banned words: ${BANNED_WORDS.join(', ')}.`,
    `- AI tells: ${AI_TELLS.map(t => `"${t}"`).join(', ')}.`
  ].join('\n');
}

const titleOf = (text: string, name: string) => /^#\s*Skill:\s*(.+)$/m.exec(text)?.[1]?.trim() ?? name;

export function listSkills(): Skill[] {
  return ORDER.map(name => {
    const raw = SKILL_FILES[name].trimEnd();
    const text = name === 'copy' ? `${raw}\n\n${lintListText()}` : raw;
    return { name, title: titleOf(raw, name), text };
  });
}

/** All skills, in order, for the system prompt. */
export function skillsPrompt(): string {
  return listSkills().map(s => s.text).join('\n\n');
}
